//! Runs every file in `test-vectors/` against the Rust core. The vectors are
//! generated by the independent JavaScript reference (`tools/make-vectors.mjs`),
//! so agreement here means two implementations agree.

use std::fs;
use std::path::{Path, PathBuf};

use evidence_core::canon::{canonicalize, format_number};
use evidence_core::json::{self, Value};
use evidence_core::verify::{verify, Options, Store};

fn root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../../test-vectors")
}

fn load(path: &Path) -> Value {
    json::parse(&fs::read(path).unwrap_or_else(|e| panic!("{}: {e}", path.display())))
        .unwrap_or_else(|e| panic!("{}: {e}", path.display()))
}

fn s<'a>(v: &'a Value, key: &str) -> Option<&'a str> {
    v.get(key).and_then(Value::as_str)
}

fn finish(kind: &str, failures: Vec<String>, total: usize) {
    assert!(total > 0, "no {kind} vectors found");
    assert!(
        failures.is_empty(),
        "{} of {total} {kind} vectors failed:\n  {}",
        failures.len(),
        failures.join("\n  ")
    );
}

#[test]
fn canonicalisation_vectors() {
    let cases = load(&root().join("canon.json"));
    let cases = cases.as_array().unwrap();
    let mut failures = Vec::new();
    for c in cases {
        let name = s(c, "name").unwrap();
        let input = s(c, "input").unwrap();
        match (
            json::parse(input.as_bytes()),
            s(c, "expected"),
            s(c, "error"),
        ) {
            (Ok(v), Some(want), _) if canonicalize(&v) == want => {}
            (Err(e), _, Some(code)) if e.code.as_str() == code => {}
            (got, want, code) => failures.push(format!(
                "{name}: got {:?}, want {want:?} / {code:?}",
                got.map(|v| canonicalize(&v))
            )),
        }
    }
    finish("canon", failures, cases.len());
}

#[test]
fn number_vectors() {
    let cases = load(&root().join("numbers.json"));
    let cases = cases.as_array().unwrap();
    let mut failures = Vec::new();
    for c in cases {
        let bits = s(c, "bits").unwrap();
        let want = s(c, "expected").unwrap();
        let got = format_number(f64::from_bits(u64::from_str_radix(bits, 16).unwrap()));
        if got != want {
            failures.push(format!("{bits}: got {got}, want {want}"));
        }
    }
    finish("number", failures, cases.len());
}

#[test]
fn object_vectors() {
    let mut dirs: Vec<PathBuf> = fs::read_dir(root().join("objects"))
        .unwrap()
        .map(|e| e.unwrap().path())
        .collect();
    dirs.sort();
    let mut failures = Vec::new();
    for dir in &dirs {
        let name = dir.file_name().unwrap().to_string_lossy().to_string();
        let case = load(&dir.join("case.json"));
        let expect = case.get("expect").unwrap();

        let attestations = fs::read(dir.join("attestations.jsonl")).ok();
        let store = (case.get("store") == Some(&Value::Bool(true))).then(|| {
            let mut store = Store::new();
            let mut files: Vec<PathBuf> = fs::read_dir(dir.join("store"))
                .unwrap()
                .map(|e| e.unwrap().path())
                .collect();
            files.sort();
            for f in files {
                store.insert(&fs::read(&f).unwrap()).unwrap();
            }
            store
        });
        let require: Vec<String> = case
            .get("require")
            .and_then(Value::as_array)
            .unwrap_or(&[])
            .iter()
            .map(|v| v.as_str().unwrap().to_string())
            .collect();

        let report = verify(
            &fs::read(dir.join("object.json")).unwrap(),
            &Options {
                attestations: attestations.as_deref(),
                store: store.as_ref(),
                require: &require,
            },
        );

        let want_ok = expect.get("ok") == Some(&Value::Bool(true));
        let got_code = report.error.as_ref().map(|e| e.code.as_str());
        let mut problems = Vec::new();
        if report.ok() != want_ok {
            problems.push(format!("ok={} ({:?})", report.ok(), report.error));
        }
        if let Some(code) = s(expect, "code") {
            if got_code != Some(code) {
                problems.push(format!("code {got_code:?}, want {code}"));
            }
        }
        if let Some(id) = s(expect, "id") {
            if report.id.as_deref() != Some(id) {
                problems.push(format!("id {:?}, want {id}", report.id));
            }
        }
        if let Some(Value::Bool(checked)) = expect.get("content_checked") {
            if report.content_checked != *checked {
                problems.push(format!("content_checked {}", report.content_checked));
            }
        }
        if let Some(Value::Object(counts)) = expect.get("attestations") {
            for (purpose, n) in counts {
                let got = report.attestations.get(purpose).copied().unwrap_or(0) as f64;
                if Value::Number(got) != *n {
                    problems.push(format!("{purpose} attestations {got}"));
                }
            }
        }
        if !problems.is_empty() {
            failures.push(format!("{name}: {}", problems.join("; ")));
        }
    }
    finish("object", failures, dirs.len());
}
